use vstd::prelude::*;

verus! {
    // Append two read‐only slices of i32, returning a new Vec<i32>
    // satisfying:
    //   1. c.len() = a.len() + b.len()
    //   2. ∀ i < a.len(): c[i] == a[i]
    //   3. ∀ j < b.len(): c[a.len() + j] == b[j]
    fn append_array(a: &[i32], b: &[i32]) -> (c: Vec<i32>)
        ensures
            c.len() == a.len() + b.len(),
            forall |i: usize| i < a.len() ==> c[i] == a[i],
            forall |j: usize| j < b.len() ==> c[a.len() + j] == b[j],
    {
        let mut c: Vec<i32> = Vec::new();
        // (Optional) reserve the full capacity up‐front
        c.reserve(a.len() + b.len());

        // Copy the first slice a into c
        let mut i: usize = 0;
        while i < a.len()
            invariant
                i <= a.len(),
                c.len() == i,
                forall |k: usize| k < i ==> c[k] == a[k],
            decreases a.len() - i,
        {
            c.push(a[i]);
            i += 1;
        }

        // Copy the second slice b into c
        let mut j: usize = 0;
        while j < b.len()
            invariant
                j <= b.len(),
                c.len() == a.len() + j,
                // the first a.len() entries are still equal to a
                forall |k: usize| k < a.len() ==> c[k] == a[k],
                // the next j entries match b[0..j]
                forall |k: usize| k < j ==> c[a.len() + k] == b[k],
            decreases b.len() - j,
        {
            c.push(b[j]);
            j += 1;
        }

        c
    }
}

